style.css:
@-moz-document domain("tradingview.com") {
/* تغيير خلفية منطقة الشارت الرئيسية */
    .chart-container, .chart-container-inner, body, .layout__area--center {
        background-image: url("https://giphy.com") !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }
    /* جعل العناصر المحيطة بالشارت شبه شفافة لترى الخلفية بوضوح */
    .tv-side-toolbar, .top-properties-toolbar, .drawing-toolbar {
        background-color: rgba(28, 32, 48, 0.7) !important;
    }
}
